def signed_request(body: bytes, secret: bytes) -> dict[str, str]:
    headers = {"Content-Type": "application/json"}
    # Kolejność ma znaczenie: podpis liczony jest z treści, więc nagłówek dodajemy dopiero po niej.
    headers["X-Signature"] = hmac.new(secret, body, hashlib.sha256).hexdigest()
    return headers
